/usr/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
for p in [Path('AGENTS.md'), Path('../AGENTS.md')]:
 if p.exists(): print(p, p.read_text())
for p in sorted(Path('.').glob('pc*/etc/bind/*')): print('EXISTING',p)
for n in range(1,61):
 import re
 s=Path(f'pc{n}.startup').read_text()
 m=re.findall(r'ip address add (\\d+\\.\\d+\\.\\d+\\.\\d+)/\\d+ dev eth0',s)
 print(n, ','.join(m), 'named' if 'systemctl restart named' in s else '')
PY"

